final List<String> areasProceso = _generarAreasProceso();

List<String> _generarAreasProceso() {
  return rutasRawData
      .split('\n')
      .map((e) => e.trim())
      .where((e) => e.isNotEmpty)
      .map((e) {
        String path = e.replaceAll('// ', '').trim();
        path = path.replaceAll('NICARAGUA SUGAR ESTATES LIMITED/ INGENIO SAN ANTONIO/', '').trim();
        if (path.startsWith('/')) path = path.substring(1).trim();
        if (path.endsWith('/')) path = path.substring(0, path.length - 1).trim();
        return path.split('/').map((s) => s.trim()).join(' / ');
      })
      .where((e) => e.isNotEmpty)
      .toList();
}

